import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { skills, experiences, projects, socialLinks } from "../constants";
import cv from "../assets/images/Mohamed_Ashraf_CV.pdf";
import mylogo from "../assets/images/mylogo.png";
import nvidia from "../assets/images/nvidia.png";
import andrew from "../assets/images/andrew.png";
import A2 from "../assets/images/A2.png";
import depi from "../assets/images/depi.png";
import mlCertificate from "../assets/images/creativa.png";
import hero_ml_photo from "../assets/images/me.jpeg";

import emailjs from "@emailjs/browser";
import { useRef, Suspense } from "react";
import { Canvas } from "@react-three/fiber";
import { PerspectiveCamera, Environment } from "@react-three/drei";
import useAlert from "../hooks/useAlert";
import { Alert } from "../components";
import { LoginCharacters } from "../models";

import { VerticalTimeline, VerticalTimelineElement } from "react-vertical-timeline-component";
import "react-vertical-timeline-component/style.min.css";

const RecruiterMode = () => {
    const [scrolled, setScrolled] = useState(false);

    // Contact form state
    const formRef = useRef();
    const canvasRef = useRef();
    const [form, setForm] = useState({ name: "", email: "", message: "" });
    const { alert, showAlert, hideAlert } = useAlert();
    const [loading, setLoading] = useState(false);
    const [formState, setFormState] = useState("idle");
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

    const handleChange = ({ target: { name, value } }) => {
        setForm({ ...form, [name]: value });
    };

    const handleFocus = (fieldName) => {
        if (fieldName === "message") {
            setFormState("typing");
        } else {
            setFormState("idle");
        }
    };

    const handleBlur = () => {
        setFormState("idle");
    };

    const handleMouseMove = (e) => {
        const x = (e.clientX / window.innerWidth) * 2 - 1;
        const y = -(e.clientY / window.innerHeight) * 2 + 1;
        setMousePos({ x, y });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setLoading(true);

        emailjs
            .send(
                import.meta.env.VITE_APP_EMAILJS_SERVICE_ID,
                import.meta.env.VITE_APP_EMAILJS_TEMPLATE_ID,
                {
                    from_name: form.name,
                    from_email: form.email,
                    message: form.message,
                },
                import.meta.env.VITE_APP_EMAILJS_PUBLIC_KEY
            )
            .then(
                () => {
                    setLoading(false);
                    setFormState("success");
                    showAlert({ show: true, text: "??? Thank you! Your message has been sent successfully.", type: "success" });
                    setTimeout(() => { hideAlert(); setForm({ name: "", email: "", message: "" }); setFormState("idle"); }, 3000);
                },
                (error) => {
                    setLoading(false);
                    setFormState("error");
                    showAlert({ show: true, text: "??? Something went wrong. Please try again.", type: "danger" });
                    setTimeout(() => { setFormState("idle"); }, 2000);
                }
            );
    };

    const certificates = [
        {
            id: 1,
            name: "NVIDIA Deep Learning Certificate",
            issuer: "NVIDIA",
            image: nvidia,
            description: "Completed comprehensive training in deep learning fundamentals, neural networks, and AI model development. This certification demonstrates proficiency in building and deploying deep learning solutions using NVIDIA's cutting-edge technologies and frameworks.",
            date: "2024",
            skills: ["Deep Learning", "Neural Networks", "AI Development", "GPU Computing"]
        },
        {
            id: 2,
            name: "Machine Learning Specialization",
            issuer: "Andrew Ng - Stanford University",
            image: andrew,
            description: "Successfully completed Andrew Ng's renowned Machine Learning course covering supervised learning, unsupervised learning, and best practices in machine learning. Gained hands-on experience with algorithms including linear regression, logistic regression, neural networks, and more.",
            date: "2024",
            skills: ["Machine Learning", "Python", "Algorithms", "Data Analysis"]
        },
        {
            id: 3,
            name: "Unsupervised Learning, Recommenders, Reinforcement Learning",
            issuer: "DeepLearning.AI & Stanford University - Coursera",
            image: A2,
            description: "Advanced course covering unsupervised learning techniques including clustering and anomaly detection, building recommender systems with collaborative filtering and content-based filtering, and fundamentals of reinforcement learning.",
            date: "2026",
            skills: ["Unsupervised Learning", "Recommender Systems", "Reinforcement Learning", "Anomaly Detection"]
        },
        {
            id: 4,
            name: "Data Analytics - Microsoft Power BI Specialist",
            issuer: "Digital Egypt Pioneers Program (DEPI) - MCIT",
            image: depi,
            description: "Completed an intensive 6-month specialized program in Data Analytics, focusing on Microsoft Power BI. Gained expertise in data modeling, visualization, and business intelligence to drive data-driven decision making.",
            date: "2025",
            skills: ["Power BI", "Data Analytics", "Data Visualization", "Business Intelligence", "Query Editor"]
        },
        {
            id: 5,
            name: "Machine Learning for Data Analysis",
            issuer: "Digital Egypt Youth Program / NTI",
            image: mlCertificate,
            description: "Completed the Machine Learning for Data Analysis program (Technical 90 hrs + Freelancing 30 hrs). Focused on practical ML workflows, model evaluation, and data-driven solutions.",
            date: "17/08/2025 - 10/10/2025",
            skills: ["Machine Learning", "Data Analysis", "Model Evaluation", "Python"]
        }
    ];

    useEffect(() => {
        // Scroll to top when entering the page
        window.scrollTo(0, 0);

        const handleScroll = () => {
            setScrolled(window.scrollY > 50);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <div className="min-h-screen bg-zinc-950 text-zinc-300 font-sans selection:bg-emerald-500/30 selection:text-emerald-200">

            {/* Navbar */}
            <nav className={`fixed w-full z-50 transition-all duration-300 ${scrolled ? "bg-zinc-950/90 backdrop-blur-md text-white border-b border-zinc-800 shadow-sm py-4" : "bg-transparent text-zinc-100 py-6"}`}>
                <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
                    <div className="font-bold text-xl tracking-tight text-white group cursor-pointer hover:text-emerald-400 transition-colors">Mohamed <span className="text-emerald-500">Ashraf</span></div>
                    <div className="hidden lg:flex gap-6 items-center text-sm font-medium">
                        <a href="#home" className="hover:text-emerald-400 transition-colors">Home</a>
                        <a href="#about" className="hover:text-emerald-400 transition-colors">About</a>
                        <a href="#skills" className="hover:text-emerald-400 transition-colors">Skills</a>
                        <a href="#experience" className="hover:text-emerald-400 transition-colors">Experience</a>
                        <a href="#projects" className="hover:text-emerald-400 transition-colors">Projects</a>
                        <a href="#certificates" className="hover:text-emerald-400 transition-colors">Certificates</a>
                        <a href="#contact" className="hover:text-emerald-400 transition-colors">Contact</a>
                        <Link to="/" className={`px-4 py-1.5 border rounded-lg transition-all ${scrolled ? "bg-emerald-500 text-zinc-950 border-emerald-500 hover:bg-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.4)]" : "bg-transparent text-emerald-400 border-emerald-500/50 hover:bg-emerald-500/10"}`}>3D Mode</Link>
                    </div>
                </div>
            </nav>

            {/* Hero Section */}
            <section id="home" className="relative pt-32 pb-24 px-6 min-h-screen flex flex-col items-center justify-center bg-black text-white overflow-hidden">
                {/* Decorative elements - Neon Glows */}
                <div className="absolute top-1/2 right-1/4 w-[500px] h-[500px] -translate-y-1/2 rounded-full bg-emerald-500/20 blur-[100px] pointer-events-none"></div>

                <div className="max-w-6xl mx-auto w-full z-10 animate-fade-in-up flex flex-col items-center">

                    <div className="flex flex-col-reverse md:flex-row items-center justify-between gap-12 md:gap-8 w-full">

                        {/* Left Side: Text Content */}
                        <div className="flex flex-col text-center md:text-left justify-center flex-1 max-w-xl">
                            <h1 className="text-4xl md:text-5xl lg:text-7xl font-bold tracking-tight mb-4 text-emerald-500 drop-shadow-[0_0_15px_rgba(16,185,129,0.3)]">
                                Machine Learning
                                <br />
                                Developer
                            </h1>

                            <p className="text-base md:text-lg text-zinc-400 mb-8 leading-relaxed">
                                Building digital experiences that merge data science with intelligent engineering.
                                <br /><br />
                                Specializing in modern AI infrastructure and intelligent systems.
                            </p>

                            <div className="flex justify-center md:justify-start">
                                <a href="#contact" className="px-8 py-3 bg-emerald-500 hover:bg-emerald-400 text-black font-semibold rounded-md transition-colors shadow-[0_0_15px_rgba(16,185,129,0.4)]">
                                    Let's Connect
                                </a>
                            </div>
                        </div>

                        {/* Right Side: Profile Picture (Round) */}
                        <div className="relative w-64 h-64 md:w-80 md:h-80 lg:w-[400px] lg:h-[400px] rounded-full overflow-hidden shadow-[0_0_40px_rgba(16,185,129,0.3)] flex-shrink-0 border-2 border-emerald-500/30 group">
                            {/* Inner glowing halo */}
                            <div className="absolute inset-0 rounded-full border-2 border-emerald-400/40 group-hover:border-emerald-400/80 group-hover:shadow-[inset_0_0_50px_rgba(16,185,129,0.4)] transition-all duration-500 z-10 pointer-events-none"></div>
                            {/* Inner glow on the image itself */}
                            <div className="absolute inset-0 bg-emerald-500/10 mix-blend-overlay z-10 pointer-events-none"></div>
                            <img src={hero_ml_photo} alt="Mohamed Ashraf" className="w-full h-full object-cover relative z-0 transition-transform duration-700 group-hover:scale-105" style={{ objectPosition: "center top" }} />
                        </div>
                    </div>

                    {/* Scroll Indicator */}
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 animate-bounce">
                        <svg className="w-6 h-6 text-zinc-600 hover:text-emerald-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 14l-7 7m0 0l-7-7m7 7V3"></path></svg>
                    </div>
                </div>
            </section>

            {/* About Section */}
            <section id="about" className="py-24 px-6 bg-black border-t border-zinc-800/50">
                <div className="max-w-6xl mx-auto">
                    <div className="mb-16">
                        <h3 className="text-4xl font-bold text-white mb-4">Technical Expertise</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6 mt-16">
                        {/* Expertise Cards - CyberDev theme */}
                        <div className="bg-zinc-900/40 p-6 rounded-xl border border-zinc-800/80 hover:border-emerald-500/30 transition-all duration-300">
                            <div className="text-emerald-500 mb-4">
                                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4"></path></svg>
                            </div>
                            <h4 className="font-bold text-white mb-2">Machine Learning</h4>
                            <p className="text-sm text-zinc-400">Deep Learning, Neural Networks, PyTorch, TensorFlow</p>
                        </div>

                        <div className="bg-zinc-900/40 p-6 rounded-xl border border-zinc-800/80 hover:border-emerald-500/30 transition-all duration-300">
                            <div className="text-emerald-500 mb-4">
                                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 7v10c0 2.21 3.582 4 8 4s8-1.79 8-4V7M4 7c0 2.21 3.582 4 8 4s8-1.79 8-4M4 7c0-2.21 3.582-4 8-4s8 1.79 8 4m0 5c0 2.21-3.582 4-8 4s-8-1.79-8-4"></path></svg>
                            </div>
                            <h4 className="font-bold text-white mb-2">Data Engineering</h4>
                            <p className="text-sm text-zinc-400">Data Pipelines, SQL, NoSQL, Big Data Architectures</p>
                        </div>
                    </div>
                </div>
        </div>
            </section >

    {/* Skills Section */ }
    < section id = "skills" className = "py-24 px-6 bg-black border-t border-zinc-800/50" >
        <div className="max-w-6xl mx-auto">
            <div className="text-center mb-16">
                <h3 className="text-4xl font-bold text-white mb-4">Technical Expertise</h3>
                <p className="text-zinc-500 max-w-2xl mx-auto font-medium">A comprehensive overview of my technical expertise and proficiency levels</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 mb-16">
                {/* Frontend */}
                <div className="bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 hover:border-emerald-500/30 hover:shadow-[0_0_20px_rgba(16,185,129,0.1)] transition-all group">
                    <h4 className="font-bold text-zinc-100 mb-6 pb-2 border-b border-zinc-800 flex items-center gap-2">
                        <span className="text-emerald-500">&lt;/&gt;</span> Frontend
                    </h4>
                    <div className="space-y-5">
                        {[{ name: "React", val: 85 }, { name: "Tailwind CSS", val: 90 }, { name: "HTML/CSS", val: 95 }, { name: "JavaScript", val: 85 }].map(s => (
                            <div key={s.name}>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="font-medium text-zinc-300 group-hover:text-emerald-400 transition-colors">{s.name}</span>
                                    <span className="text-zinc-500 font-mono">{s.val}%</span>
                                </div>
                                <div className="w-full bg-zinc-800/80 rounded-full h-1.5 overflow-hidden">
                                    <div className="bg-emerald-500 h-1.5 rounded-full shadow-[0_0_10px_rgba(16,185,129,0.8)]" style={{ width: `${s.val}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Backend */}
                <div className="bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 hover:border-emerald-500/30 hover:shadow-[0_0_20px_rgba(16,185,129,0.1)] transition-all group">
                    <h4 className="font-bold text-zinc-100 mb-6 pb-2 border-b border-zinc-800 flex items-center gap-2">
                        <span className="text-emerald-500">??????</span> Backend
                    </h4>
                    <div className="space-y-5">
                        {[{ name: "Node.js", val: 80 }, { name: "Python", val: 90 }, { name: "Java", val: 85 }, { name: "C", val: 75 }].map(s => (
                            <div key={s.name}>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="font-medium text-zinc-300 group-hover:text-emerald-400 transition-colors">{s.name}</span>
                                    <span className="text-zinc-500 font-mono">{s.val}%</span>
                                </div>
                                <div className="w-full bg-zinc-800/80 rounded-full h-1.5 overflow-hidden">
                                    <div className="bg-emerald-500 h-1.5 rounded-full shadow-[0_0_10px_rgba(16,185,129,0.8)]" style={{ width: `${s.val}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Database */}
                <div className="bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 hover:border-emerald-500/30 hover:shadow-[0_0_20px_rgba(16,185,129,0.1)] transition-all group">
                    <h4 className="font-bold text-zinc-100 mb-6 pb-2 border-b border-zinc-800 flex items-center gap-2">
                        <span className="text-emerald-500">???????</span> Database
                    </h4>
                    <div className="space-y-5">
                        {[{ name: "SQL", val: 90 }, { name: "MySQL / PostgreSQL", val: 85 }].map(s => (
                            <div key={s.name}>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="font-medium text-zinc-300 group-hover:text-emerald-400 transition-colors">{s.name}</span>
                                    <span className="text-zinc-500 font-mono">{s.val}%</span>
                                </div>
                                <div className="w-full bg-zinc-800/80 rounded-full h-1.5 overflow-hidden">
                                    <div className="bg-emerald-500 h-1.5 rounded-full shadow-[0_0_10px_rgba(16,185,129,0.8)]" style={{ width: `${s.val}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Tools */}
                <div className="bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 hover:border-emerald-500/30 hover:shadow-[0_0_20px_rgba(16,185,129,0.1)] transition-all group">
                    <h4 className="font-bold text-zinc-100 mb-6 pb-2 border-b border-zinc-800 flex items-center gap-2">
                        <span className="text-emerald-500">???????</span> Tools
                    </h4>
                    <div className="space-y-5">
                        {[{ name: "Git/GitHub", val: 95 }, { name: "Power BI", val: 85 }, { name: "Agile", val: 80 }].map(s => (
                            <div key={s.name}>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="font-medium text-zinc-300 group-hover:text-emerald-400 transition-colors">{s.name}</span>
                                    <span className="text-zinc-500 font-mono">{s.val}%</span>
                                </div>
                                <div className="w-full bg-zinc-800/80 rounded-full h-1.5 overflow-hidden">
                                    <div className="bg-emerald-500 h-1.5 rounded-full shadow-[0_0_10px_rgba(16,185,129,0.8)]" style={{ width: `${s.val}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <div className="text-center">
                <h4 className="font-bold text-zinc-300 mb-8 text-xl">Technology Stack</h4>
                <div className="flex flex-wrap justify-center gap-4">
                    {skills.map((skill) => (
                        <div key={skill.name} className="px-5 py-2.5 bg-zinc-900 rounded-full text-sm font-medium text-zinc-300 border border-zinc-800 hover:border-emerald-500/50 hover:text-emerald-400 hover:bg-emerald-500/5 transition-all shadow-sm flex items-center gap-3 cursor-default">
                            <img src={skill.imageUrl} alt={skill.name} className="w-5 h-5 object-contain drop-shadow-md" />
                            {skill.name}
                        </div>
                    ))}
                </div>
            </div>
        </div>
            </section >

    {/* Experience Section */ }
    < section id = "experience" className = "py-24 px-6 bg-black border-t border-zinc-800/50" >
        <div className="max-w-4xl mx-auto">
            <div className="text-center mb-16">
                <h3 className="text-4xl font-bold text-white mb-4">Work Experience</h3>
                <p className="text-zinc-400 max-w-2xl mx-auto">My professional journey and the roles that have shaped my expertise</p>
            </div>

            <div className="flex mt-12 justify-center">
                <VerticalTimeline lineColor="#27272a">
                    {experiences.map((experience, index) => (
                        <VerticalTimelineElement
                            key={experience.company_name}
                            date={experience.date}
                            dateClassName="text-emerald-400 font-semibold tracking-wide ml-4"
                            iconStyle={{ background: '#09090b', boxShadow: "0 0 0 4px #10b981, inset 0 2px 0 rgba(0,0,0,.08), 0 0 20px rgba(16,185,129,0.5)" }}
                            icon={
                                <div className='flex items-center justify-center w-full h-full rounded-full bg-zinc-900 border border-zinc-800'>
                                    <img
                                        src={experience.icon}
                                        alt={experience.company_name}
                                        className='w-[60%] h-[60%] object-contain drop-shadow-md'
                                    />
                                </div>
                            }
                            contentStyle={{
                                borderBottom: "4px",
                                borderStyle: "solid",
                                borderBottomColor: "#10b981",
                                boxShadow: "0 4px 20px -2px rgba(0,0,0,0.5)",
                                background: '#18181b', // zinc-900
                                color: '#fff',
                                borderRadius: '1rem',
                                border: '1px solid #27272a' // zinc-800
                            }}
                            contentArrowStyle={{
                                borderRight: `7px solid #27272a`
                            }}
                        >
                            <div>
                                <h3 className='text-xl font-bold text-white font-poppins'>
                                    {experience.title}
                                </h3>
                                <p
                                    className='text-base font-semibold text-emerald-500'
                                    style={{ margin: 0 }}
                                >
                                    {experience.company_name}
                                </p>
                            </div>

                            <ul className='my-5 ml-5 space-y-2 list-disc marker:text-emerald-500'>
                                {experience.points.map((point, index) => (
                                    <li
                                        key={`experience-point-${index}`}
                                        className='pl-1 text-sm font-normal text-zinc-400 leading-relaxed'
                                    >
                                        {point}
                                    </li>
                                ))}
                            </ul>
                        </VerticalTimelineElement>
                    ))}
                </VerticalTimeline>
            </div>
        </div>
            </section >

    {/* Projects Section */ }
    < section id = "projects" className = "py-24 px-6 bg-black border-t border-zinc-800/50" >
        <div className="max-w-6xl mx-auto">
            <div className="text-center mb-16">
                <h3 className="text-4xl font-bold text-white mb-4">Featured Projects</h3>
                <p className="text-zinc-500 max-w-2xl mx-auto">A showcase of my recent work and personal projects that demonstrate my skills and creativity</p>
            </div>

            <div className='grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 my-10'>
                {projects.map((project, index) => (
                    <div
                        className='bg-zinc-900 rounded-2xl overflow-hidden shadow-lg border border-zinc-800 flex flex-col group hover:border-emerald-500/50 hover:shadow-[0_0_25px_rgba(16,185,129,0.15)] transition-all duration-300'
                        key={project.name}
                    >
                        {/* Colored Header with Icon or Image */}
                        <div className={`card-header h-40 relative flex justify-center items-center ${project.theme.replace('btn-back', 'bg-gradient')}`}>
                            {!project.imageUrl && (
                                <div className='absolute inset-0 bg-zinc-950/40 backdrop-blur-[2px] z-10' />
                            )}

                            {project.imageUrl ? (
                                <img
                                    src={project.imageUrl}
                                    alt={project.name}
                                    className='w-full h-full object-cover absolute inset-0 z-0 opacity-80 group-hover:opacity-100 group-hover:scale-110 transition-transform duration-500'
                                    style={{ objectPosition: 'center' }}
                                />
                            ) : (
                                <img
                                    src={project.iconUrl}
                                    alt={project.name}
                                    className='w-1/2 h-1/2 object-contain relative z-20 group-hover:scale-110 transition-transform duration-500 drop-shadow-[0_0_10px_rgba(255,255,255,0.3)]'
                                />
                            )}
                        </div>

                        {/* Card Body */}
                        <div className='p-6 flex flex-col flex-1 relative z-20 bg-zinc-900'>
                            <div className='flex flex-wrap justify-between items-start gap-2 mb-4'>
                                <h4 className='text-xl font-bold font-poppins text-zinc-100 leading-tight break-words min-w-0 pr-2 group-hover:text-emerald-400 transition-colors'>
                                    {project.name}
                                </h4>
                                {project.category && (
                                    <span className='px-2.5 py-1 bg-emerald-500/10 text-emerald-400 rounded text-[10px] font-semibold border border-emerald-500/20 whitespace-nowrap flex-shrink-0 tracking-wide uppercase'>
                                        {project.category}
                                    </span>
                                )}
                            </div>

                            <p className='text-zinc-400 text-sm leading-relaxed mb-6 flex-1'>
                                {project.description}
                            </p>

                            <div className='mt-auto flex justify-between items-center'>
                                {project.link && (
                                    <a
                                        href={project.link}
                                        target='_blank'
                                        rel='noopener noreferrer'
                                        className='inline-flex items-center gap-2 font-semibold text-emerald-500 hover:text-emerald-400 transition-colors text-sm'
                                    >
                                        Visit Site
                                        <svg className="w-4 h-4 transition-transform group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
